import assert from 'node:assert/strict';
import { test } from 'node:test';
import { readFileSync } from 'node:fs';
import { handle } from '../contributor-bot.mjs';
import { createGitHubClient } from '../lib/github-client.mjs';
import { evaluateChecks } from './checks.mjs';
import { evaluatePolicy } from './policy.mjs';
import { handleGuardianCommand } from './commands.mjs';
import { createApi, makePull, baseConfig, NOW } from './test-helpers.mjs';
import { isDismissibleFinding } from './readiness.mjs';
import { escapeInline, codeSpan } from './util.mjs';
import { loadConfig } from './index.mjs';
function contributor(title='Improve a guide',labels=[]){const issue={number:1,title,state:'open',labels,assignees:[]};const comments=[];const calls=[];const event={issue,comment:{id:456,body:'/assign',user:{login:'alice',type:'User'}}};const api={issue:async()=>issue,comments:async()=>comments,assignedOpenIssues:async()=>[],comment:async(_,body)=>comments.push({body,user:{login:'github-actions[bot]',type:'Bot'}}),assign:async(_,login)=>{calls.push('assign');issue.assignees.push({login});},unassign:async()=>calls.push('unassign')};return {event,api,issue,comments,calls};}
for(const title of ['Fix credential access','Review Keychain identity','Protect authentication','Rotate token','Password storage'])test(`sensitive issue cannot be claimed: ${title}`,async()=>{const s=contributor(title);await handle(s.event,s.api);assert.deepEqual(s.calls,[]);});
for(const label of ['maintainer-only','restricted','no-auto-assign'])test(`restricted label ${label} blocks automated assignment`,async()=>{const s=contributor('A task',[{name:label}]);await handle(s.event,s.api);assert.deepEqual(s.calls,[]);});
test('duplicate assignment event does not repeat mutation or reply',async()=>{const s=contributor();await handle(s.event,s.api);await handle(s.event,s.api);assert.deepEqual(s.calls,['assign']);assert.equal(s.comments.length,1);});
test('a competing maintainer assignment is not overwritten',async()=>{const s=contributor();s.api.assign=async()=>{s.issue.assignees.push({login:'bob'},{login:'alice'});};await handle(s.event,s.api);assert.deepEqual(s.calls,['unassign']);});
test('assignment permission denial produces guidance without retries',async()=>{const s=contributor();let attempts=0;s.api.assign=async()=>{attempts++;throw Object.assign(new Error('not accessible'),{status:403});};await handle(s.event,s.api);assert.equal(attempts,1);assert.match(s.comments[0].body,/maintainer/);});
test('forged event-marker comment cannot suppress an assignment',async()=>{const s=contributor();s.comments.push({body:'<!-- codovyn-contributor-event:456 -->',user:{login:'alice',type:'User'}});await handle(s.event,s.api);assert.deepEqual(s.calls,['assign']);});
test('bot events cannot trigger contributor actions',async()=>{const s=contributor();s.event.comment.user={login:'helper[bot]',type:'Bot'};await handle(s.event,s.api);assert.equal(s.comments.length,0);});
test('a member without write permission gets no maintainer bypass',async()=>{const pull=makePull({author_association:'MEMBER',body:''});const api=createApi({pull,permissions:{alice:{permission:'read'}}});assert.equal((await evaluatePolicy({api,pull,repository:api.repository})).status,'blocked');});
test('unknown repository requirements cannot become ready',async()=>{const api=createApi();assert.equal((await evaluateChecks({api,pull:makePull(),changedFiles:['README.md'],repositoryPolicy:{unavailable:['rulesets:403']},now:NOW})).status,'unknown');});
for(const id of ['checks.no-data','checks.repository-policy-unknown','checks.expected-missing','checks.failed.test','checks.security-failed','policy.invalid-pull','pr.merge-conflict'])test(`safety finding cannot be dismissed: ${id}`,()=>assert.equal(isDismissibleFinding(id),false));
test('authorized dismissal remains available for non-safety false positives',async()=>{const api=createApi({permissions:{alice:{permission:'maintain'}}});const finding={id:'review.manual-followup',severity:'warning',title:'Follow up',detail:'Synthetic non-safety example'};let persisted;await handleGuardianCommand({api,event:{issue:{number:90,pull_request:{}},comment:{body:'/guardian dismiss review.manual-followup verified false positive',user:{login:'alice',type:'User'}}},config:baseConfig(),now:NOW,evaluate:async()=>({pull:makePull(),policy:{status:'compliant',findings:[]},checks:{status:'passed',findings:[]},reviews:{status:'none',findings:[finding]},outcome:{state:'READY_FOR_MAINTAINER_REVIEW',findings:[finding],dismissals:{}}}),persist:async x=>{persisted=x;return {outcome:x.snapshot.outcome};}});assert.equal(persisted.snapshot.outcome.dismissals[finding.id].by,'alice');});
test('Guardian command replay cannot duplicate responses',async()=>{const api=createApi();const event={issue:{number:90,pull_request:{}},comment:{id:123,body:'/guardian help',user:{login:'alice',type:'User'}}};const options={api,event,config:baseConfig(),now:NOW};await handleGuardianCommand(options);await handleGuardianCommand(options);assert.equal(api.state.comments.length,1);});
test('pagination exhaustion fails closed instead of authorizing a partial result',async()=>{const api=createGitHubClient({token:'fixture',owner:'Gautam-aman',repo:'CODOVYN',fetchImpl:async()=>new Response(JSON.stringify(Array.from({length:100},()=>({}))),{status:200})});await assert.rejects(api.listOpenPulls({maxPages:1,maxItems:100}),/incomplete/);});
test('incomplete search cannot authorize reassignment policy',async()=>{const api=createGitHubClient({token:'fixture',owner:'Gautam-aman',repo:'CODOVYN',fetchImpl:async()=>new Response(JSON.stringify({items:[],incomplete_results:true}),{status:200})});await assert.rejects(api.searchOpenPullsForIssue(1),/incomplete/);});
test('untrusted Markdown, HTML and mentions are escaped',()=>{const s=escapeInline('@everyone <script> [click](https://bad.invalid) *bold*');assert.ok(!s.includes('@everyone'));assert.ok(!s.includes('<script>'));assert.ok(s.includes('\\['));assert.equal(codeSpan('CHECKS_FAILED'),'`CHECKS_FAILED`');});
test('default rollout is dry and has no AI reviewer or notification',()=>{const c=loadConfig({});assert.ok(c.dryRun);assert.equal(c.aiReviewEnabled,false);assert.equal(c.notify,false);});
for(const name of ['contributor-bot','pr-assignment-bot','guardian'])test(`privileged ${name} uses trusted source and shared serialization`,()=>{const s=readFileSync(`.github/workflows/${name}.yml`,'utf8');assert.ok(s.includes('ref: ${{ github.event.repository.default_branch }}'));assert.ok(s.includes('group: community-reconcile-${{ github.repository }}'));assert.ok(s.includes('persist-credentials: false'));assert.ok(!s.includes('pull_request.head'));assert.ok(!s.includes('secrets.'));if(name!=='guardian')assert.ok(s.includes("vars.COMMUNITY_BOTS_ENABLED == 'true'"));});
test('bot test workflow is read only and runs untrusted code only without write scopes',()=>{const s=readFileSync('.github/workflows/guardian-tests.yml','utf8');assert.ok(s.includes('pull_request:'));assert.ok(s.includes('contents: read'));assert.ok(!s.includes(': write'));assert.ok(!/^  pull_request_target:/m.test(s));});
